BEGIN TRANSACTION;
CREATE TABLE acide_startups (
    id VARCHAR(100) PRIMARY KEY,
    startup_name VARCHAR(255) NOT NULL,
    founder_names TEXT DEFAULT '[]',
    department VARCHAR(255) NOT NULL,
    founded_year INTEGER DEFAULT 2024,
    tagline TEXT,
    description TEXT,
    revenue_stage VARCHAR(100) DEFAULT 'Incubated',
    logo_url TEXT,
    website_url TEXT,
    mentors TEXT DEFAULT '[]',
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE alumni_mentorship_requests (
        id TEXT PRIMARY KEY,
        alumni_id TEXT NOT NULL,
        alumni_name TEXT NOT NULL,
        student_id TEXT NOT NULL,
        student_name TEXT NOT NULL,
        student_department TEXT NOT NULL,
        student_register_number TEXT NOT NULL,
        preferred_topic TEXT NOT NULL,
        message TEXT NOT NULL,
        status TEXT DEFAULT 'pending',
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE alumni_opportunities (
    id VARCHAR(100) PRIMARY KEY,
    alumni_id VARCHAR(100) NOT NULL,
    alumni_name VARCHAR(255) NOT NULL,
    company_name VARCHAR(255) NOT NULL,
    role_title VARCHAR(255) NOT NULL,
    location VARCHAR(255) NOT NULL,
    opportunity_type VARCHAR(50) DEFAULT 'Job',
    description TEXT NOT NULL,
    apply_link_or_email VARCHAR(255) NOT NULL,
    posted_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE alumni_profiles (
        id TEXT PRIMARY KEY,
        user_id TEXT,
        name TEXT NOT NULL,
        email TEXT NOT NULL UNIQUE,
        phone TEXT,
        department_code TEXT NOT NULL,
        batch_year INTEGER NOT NULL,
        degree TEXT NOT NULL,
        current_organization TEXT NOT NULL,
        designation TEXT NOT NULL,
        industry TEXT NOT NULL,
        location TEXT NOT NULL,
        linkedin_url TEXT,
        bio TEXT,
        skills TEXT DEFAULT '[]',
        is_mentor INTEGER DEFAULT 0,
        mentorship_areas TEXT DEFAULT '[]',
        visibility TEXT DEFAULT 'public',
        avatar_url TEXT,
        is_verified INTEGER DEFAULT 1,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE alumni_stories (
    id VARCHAR(100) PRIMARY KEY,
    alumni_id VARCHAR(100) NOT NULL,
    alumni_name VARCHAR(255) NOT NULL,
    batch_year INTEGER NOT NULL,
    department_code VARCHAR(50) NOT NULL,
    title VARCHAR(255) NOT NULL,
    story_text TEXT NOT NULL,
    current_role VARCHAR(255) NOT NULL,
    photo_url TEXT,
    published_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE announcements (
    id VARCHAR(100) PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    content TEXT NOT NULL,
    audience TEXT DEFAULT '["student","faculty","parent","admin"]',
    priority VARCHAR(50) DEFAULT 'normal',
    type VARCHAR(50) DEFAULT 'info',
    department_id VARCHAR(100),
    created_by VARCHAR(100),
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE attendance_records (
    id VARCHAR(100) PRIMARY KEY,
    student_id VARCHAR(100) NOT NULL,
    course_id VARCHAR(100) NOT NULL,
    date DATE NOT NULL,
    session VARCHAR(10) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'present',
    marked_by VARCHAR(100),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(student_id, course_id, date, session)
);
CREATE TABLE audit_logs (
        id TEXT PRIMARY KEY,
        user_id TEXT,
        action TEXT NOT NULL,
        resource_type TEXT,
        resource_id TEXT,
        details TEXT DEFAULT '{}',
        ip_address TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE club_members (
        id TEXT PRIMARY KEY,
        club_id TEXT NOT NULL,
        user_id TEXT NOT NULL,
        student_name TEXT,
        register_number TEXT,
        status TEXT DEFAULT 'active',
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE courses (
        id TEXT PRIMARY KEY,
        code TEXT NOT NULL,
        title TEXT NOT NULL,
        department_id TEXT,
        programme_id TEXT,
        semester INTEGER DEFAULT 1,
        credits INTEGER DEFAULT 4,
        hours_per_week INTEGER DEFAULT 5,
        course_type TEXT DEFAULT 'Major Core',
        syllabus_status TEXT DEFAULT 'Approved',
        faculty_id TEXT,
        is_active BOOLEAN DEFAULT 1,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE departments (
        id TEXT PRIMARY KEY,
        name TEXT UNIQUE NOT NULL,
        code TEXT UNIQUE NOT NULL,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE device_tokens (
    id VARCHAR(100) PRIMARY KEY,
    user_id VARCHAR(100) NOT NULL,
    token TEXT NOT NULL UNIQUE,
    device_type VARCHAR(50) DEFAULT 'web',
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE e_content (
    id VARCHAR(100) PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    description TEXT,
    category VARCHAR(100) NOT NULL,
    department VARCHAR(100) NOT NULL,
    course_code VARCHAR(50) NOT NULL,
    course_title VARCHAR(255) NOT NULL,
    semester INTEGER DEFAULT 1,
    faculty_id VARCHAR(100) NOT NULL,
    faculty_name VARCHAR(255) NOT NULL,
    content_type VARCHAR(50) DEFAULT 'file',
    file_url TEXT,
    signed_url TEXT,
    external_url TEXT,
    thumbnail_url TEXT,
    duration_minutes INTEGER DEFAULT 20,
    tags TEXT DEFAULT '[]',
    status VARCHAR(50) DEFAULT 'published',
    views_count INTEGER DEFAULT 0,
    likes_count INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE econtent_bookmarks (
    id VARCHAR(100) PRIMARY KEY,
    user_id VARCHAR(100) NOT NULL,
    content_id VARCHAR(100) NOT NULL,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE econtent_progress (
    id VARCHAR(100) PRIMARY KEY,
    user_id VARCHAR(100) NOT NULL,
    content_id VARCHAR(100) NOT NULL,
    progress_percentage INTEGER DEFAULT 0,
    last_position_seconds INTEGER DEFAULT 0,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE enrollments (
    id VARCHAR(100) PRIMARY KEY,
    student_id VARCHAR(100) NOT NULL,
    course_id VARCHAR(100) NOT NULL,
    semester INTEGER DEFAULT 1,
    academic_year VARCHAR(50) DEFAULT '2026-2027',
    status VARCHAR(50) DEFAULT 'enrolled',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE event_registrations (
        id TEXT PRIMARY KEY,
        event_id TEXT NOT NULL,
        user_id TEXT NOT NULL,
        registration_number TEXT,
        status TEXT DEFAULT 'registered',
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE events (
        id TEXT PRIMARY KEY,
        title TEXT NOT NULL,
        description TEXT,
        category TEXT DEFAULT 'Technical',
        department TEXT DEFAULT 'College',
        venue TEXT NOT NULL,
        start_date TEXT NOT NULL,
        end_date TEXT NOT NULL,
        time TEXT DEFAULT '09:30 AM - 04:30 PM',
        max_capacity INTEGER DEFAULT 200,
        registered_count INTEGER DEFAULT 0,
        is_registration_open BOOLEAN DEFAULT 1,
        poster_url TEXT,
        speaker_details TEXT,
        status TEXT DEFAULT 'upcoming',
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE facility_bookings (
        id TEXT PRIMARY KEY,
        facility_name TEXT NOT NULL,
        booking_date TEXT NOT NULL,
        time_slot TEXT NOT NULL,
        purpose TEXT NOT NULL,
        organizer_name TEXT NOT NULL,
        department TEXT NOT NULL,
        expected_attendees INTEGER DEFAULT 50,
        status TEXT DEFAULT 'approved',
        remarks TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE faculty (
        id TEXT PRIMARY KEY,
        user_id TEXT NOT NULL,
        employee_id TEXT UNIQUE NOT NULL,
        designation TEXT DEFAULT 'Assistant Professor',
        department_id TEXT,
        is_active BOOLEAN DEFAULT 1,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    , qualification VARCHAR(255) DEFAULT 'Ph.D. Computer Science', specialization VARCHAR(255) DEFAULT 'Cloud Computing and AI');
CREATE TABLE faculty_publications (
    id VARCHAR(100) PRIMARY KEY,
    faculty_id VARCHAR(100) NOT NULL,
    faculty_name VARCHAR(255) NOT NULL,
    title VARCHAR(255) NOT NULL,
    authors TEXT DEFAULT '[]',
    department_code VARCHAR(50) NOT NULL,
    journal_name VARCHAR(255) NOT NULL,
    indexing VARCHAR(100) DEFAULT 'Scopus',
    impact_factor NUMERIC(6,2),
    issn_isbn VARCHAR(100),
    volume_issue_pages VARCHAR(255),
    publication_year INTEGER NOT NULL,
    doi_or_url TEXT,
    paper_type VARCHAR(100) DEFAULT 'Journal',
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE ict_assets (
        id TEXT PRIMARY KEY,
        asset_tag TEXT NOT NULL,
        name TEXT NOT NULL,
        category TEXT NOT NULL,
        location TEXT NOT NULL,
        specifications TEXT,
        warranty_end_date TEXT,
        vendor TEXT,
        health_status TEXT DEFAULT 'Operational',
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE iedc_projects (
        id TEXT PRIMARY KEY,
        title TEXT NOT NULL,
        lead_student TEXT NOT NULL,
        faculty_mentor TEXT NOT NULL,
        domain TEXT NOT NULL,
        funding_agency TEXT DEFAULT 'IEDC DST / MSME',
        grant_amount REAL DEFAULT 25000.0,
        trl_level INTEGER DEFAULT 4,
        status TEXT DEFAULT 'Incubating',
        patent_filed BOOLEAN DEFAULT 0,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE iqac_action_items (
    id VARCHAR(100) PRIMARY KEY,
    meeting_id VARCHAR(100),
    title VARCHAR(255) NOT NULL,
    responsible_person_or_dept VARCHAR(255) NOT NULL,
    target_date VARCHAR(50) NOT NULL,
    status VARCHAR(50) DEFAULT 'Pending',
    evidence_url TEXT,
    remarks TEXT,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE iqac_aqar_documents (
    id VARCHAR(100) PRIMARY KEY,
    academic_year VARCHAR(50) NOT NULL,
    criteria_number INTEGER DEFAULT 1,
    criteria_name VARCHAR(255) NOT NULL,
    file_title VARCHAR(255) NOT NULL,
    document_url TEXT NOT NULL,
    submitted_to_naac BOOLEAN DEFAULT true,
    submission_date VARCHAR(50) NOT NULL,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE iqac_feedback_cycles (
    id VARCHAR(100) PRIMARY KEY,
    academic_year VARCHAR(50) NOT NULL,
    cycle_name VARCHAR(255) NOT NULL,
    stakeholder_type VARCHAR(100) NOT NULL,
    start_date VARCHAR(50) NOT NULL,
    end_date VARCHAR(50) NOT NULL,
    total_responses INTEGER DEFAULT 0,
    satisfaction_rate REAL DEFAULT 0.0,
    status VARCHAR(50) DEFAULT 'Active',
    action_taken_report_url TEXT,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE iqac_initiatives (
    id VARCHAR(100) PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    academic_year VARCHAR(50) DEFAULT '2025-2026',
    coordinator VARCHAR(255) NOT NULL,
    objectives TEXT NOT NULL,
    target_kpi TEXT NOT NULL,
    status VARCHAR(50) DEFAULT 'Active',
    impact_metrics TEXT,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE iqac_meetings (
    id VARCHAR(100) PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    meeting_number VARCHAR(100) NOT NULL,
    meeting_date VARCHAR(50) NOT NULL,
    venue VARCHAR(255) DEFAULT 'IQAC Conference Room',
    attendees TEXT DEFAULT '[]',
    agenda TEXT DEFAULT '[]',
    minutes TEXT,
    decisions TEXT DEFAULT '[]',
    action_items_count INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE library_books (
        id TEXT PRIMARY KEY,
        title TEXT NOT NULL,
        author TEXT NOT NULL,
        isbn TEXT,
        accession_no TEXT NOT NULL,
        department TEXT,
        category TEXT DEFAULT 'General',
        total_copies INTEGER DEFAULT 1,
        available_copies INTEGER DEFAULT 1,
        shelf_location TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE library_loans (
        id TEXT PRIMARY KEY,
        book_id TEXT,
        student_register_number TEXT NOT NULL,
        student_name TEXT,
        issue_date TEXT NOT NULL,
        due_date TEXT NOT NULL,
        return_date TEXT,
        fine_amount REAL DEFAULT 0.0,
        status TEXT DEFAULT 'issued',
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE marks (
    id VARCHAR(100) PRIMARY KEY,
    student_id VARCHAR(100) NOT NULL,
    course_id VARCHAR(100) NOT NULL,
    assessment_type VARCHAR(50) NOT NULL,
    marks_obtained REAL NOT NULL,
    max_marks REAL NOT NULL DEFAULT 100.0,
    academic_year VARCHAR(50) DEFAULT '2026-2027',
    semester INTEGER DEFAULT 1,
    entered_by VARCHAR(100),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE mentoring_goals (
    id VARCHAR(100) PRIMARY KEY,
    student_id VARCHAR(100) NOT NULL,
    faculty_id VARCHAR(100),
    title VARCHAR(255) NOT NULL,
    description TEXT,
    target_date VARCHAR(50),
    status VARCHAR(50) DEFAULT 'pending',
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE mentoring_records (
    id VARCHAR(100) PRIMARY KEY,
    student_id VARCHAR(100) NOT NULL,
    faculty_id VARCHAR(100) NOT NULL,
    meeting_date VARCHAR(50) NOT NULL,
    meeting_type VARCHAR(100) NOT NULL,
    academic_notes TEXT,
    personal_notes TEXT,
    goals TEXT,
    follow_up TEXT,
    next_meeting VARCHAR(50),
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE mentorship_assignments (
    id VARCHAR(100) PRIMARY KEY,
    student_id VARCHAR(100) NOT NULL,
    faculty_id VARCHAR(100) NOT NULL,
    assigned_date VARCHAR(50),
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE notifications (
    id VARCHAR(100) PRIMARY KEY,
    user_id VARCHAR(100) NOT NULL,
    title VARCHAR(255) NOT NULL,
    message TEXT NOT NULL,
    type VARCHAR(50) DEFAULT 'info',
    entity_type VARCHAR(100),
    entity_id VARCHAR(100),
    link TEXT,
    read BOOLEAN DEFAULT false,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE outpasses (
        id TEXT PRIMARY KEY,
        student_id TEXT,
        student_name TEXT,
        register_number TEXT,
        hostel_block TEXT,
        room_number TEXT,
        outpass_type TEXT DEFAULT 'Day Outpass',
        departure_time TEXT NOT NULL,
        expected_return TEXT NOT NULL,
        reason TEXT NOT NULL,
        parent_consent_status TEXT DEFAULT 'verified',
        warden_approval_status TEXT DEFAULT 'pending',
        actual_return_time TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE parents (
        id TEXT PRIMARY KEY,
        user_id TEXT NOT NULL,
        relation TEXT DEFAULT 'Parent',
        ward_student_id TEXT,
        is_active BOOLEAN DEFAULT 1,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE placement_applications (
        id TEXT PRIMARY KEY,
        drive_id TEXT NOT NULL,
        student_id TEXT NOT NULL,
        register_number TEXT,
        student_name TEXT,
        cgpa REAL,
        status TEXT DEFAULT 'applied',
        interview_date TEXT,
        notes TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    , user_id TEXT, department TEXT, company_name TEXT, role_title TEXT, ctc_range TEXT, cgpa_at_application REAL, attendance_at_application REAL, updated_at TEXT);
CREATE TABLE placement_drives (
        id TEXT PRIMARY KEY,
        company_name TEXT NOT NULL,
        role_title TEXT NOT NULL,
        ctc_lpa REAL NOT NULL,
        drive_date TEXT NOT NULL,
        venue TEXT NOT NULL,
        eligibility_criteria TEXT,
        eligible_programmes TEXT DEFAULT '[]',
        status TEXT DEFAULT 'upcoming',
        registered_count INTEGER DEFAULT 0,
        selected_count INTEGER DEFAULT 0,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE pragya_knowledge_base (
    id VARCHAR(100) PRIMARY KEY,
    category VARCHAR(100) NOT NULL,
    topic VARCHAR(255) NOT NULL,
    question_patterns TEXT NOT NULL,
    answer TEXT NOT NULL,
    quick_buttons TEXT DEFAULT '[]',
    sources TEXT DEFAULT '["SFRC Institutional Guide"]',
    keywords TEXT,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE programmes (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        code TEXT NOT NULL,
        degree_level TEXT NOT NULL,
        department_id TEXT,
        sanctioned_intake INTEGER DEFAULT 60,
        regulation_batch TEXT DEFAULT '2023 - 2026 (OBE)',
        is_active BOOLEAN DEFAULT 1,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE research_projects (
    id VARCHAR(100) PRIMARY KEY,
    faculty_id VARCHAR(100) NOT NULL,
    title VARCHAR(255) NOT NULL,
    principal_investigator VARCHAR(255) NOT NULL,
    co_investigator VARCHAR(255),
    department_code VARCHAR(50) NOT NULL,
    funding_agency VARCHAR(255) NOT NULL,
    project_type VARCHAR(100) DEFAULT 'Major',
    sanctioned_amount NUMERIC(14,2) NOT NULL,
    start_date VARCHAR(50) NOT NULL,
    end_date VARCHAR(50) NOT NULL,
    status VARCHAR(50) DEFAULT 'Ongoing',
    description TEXT,
    grant_sanction_order VARCHAR(255),
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE sports_memberships (
        id TEXT PRIMARY KEY,
        team_id TEXT NOT NULL,
        user_id TEXT NOT NULL,
        student_name TEXT,
        register_number TEXT,
        status TEXT DEFAULT 'active',
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE student_clubs (
        id TEXT PRIMARY KEY,
        activity_name TEXT NOT NULL,
        unit_type TEXT NOT NULL,
        activity_date TEXT NOT NULL,
        venue TEXT NOT NULL,
        description TEXT,
        volunteer_count INTEGER DEFAULT 50,
        credits INTEGER DEFAULT 1,
        status TEXT DEFAULT 'completed',
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE student_grievances (
        id TEXT PRIMARY KEY,
        reference TEXT NOT NULL UNIQUE,
        user_id TEXT NOT NULL,
        reporter_name TEXT,
        reporter_email TEXT,
        category TEXT NOT NULL,
        subject TEXT NOT NULL,
        description TEXT NOT NULL,
        is_anonymous INTEGER DEFAULT 0,
        status TEXT DEFAULT 'Received',
        admin_response_notes TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
        resolved_at TEXT
    );
CREATE TABLE student_leaves (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL,
    student_id UUID,
    student_name VARCHAR(255),
    register_number VARCHAR(100),
    leave_type VARCHAR(100) NOT NULL,
    reason TEXT NOT NULL,
    from_date DATE NOT NULL,
    to_date DATE NOT NULL,
    total_days NUMERIC(4,1) DEFAULT 1.0,
    status VARCHAR(50) DEFAULT 'pending',
    approval_remarks TEXT,
    approved_by UUID,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE students (
        id TEXT PRIMARY KEY,
        user_id TEXT NOT NULL,
        register_number TEXT UNIQUE NOT NULL,
        current_semester INTEGER DEFAULT 1,
        department_id TEXT,
        programme_id TEXT,
        section TEXT DEFAULT 'A',
        batch TEXT DEFAULT '2023-2026',
        date_of_birth TEXT,
        blood_group TEXT,
        permanent_address TEXT,
        emergency_contact TEXT,
        abc_id TEXT,
        apaar_id TEXT,
        preferences TEXT DEFAULT '{"email_notifications": true, "sms_alerts": true}',
        is_active BOOLEAN DEFAULT 1,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE timetables (
    id VARCHAR(100) PRIMARY KEY,
    course_id VARCHAR(100),
    programme_id VARCHAR(100),
    faculty_id VARCHAR(100),
    day_of_week INTEGER NOT NULL,
    period_number INTEGER NOT NULL,
    start_time VARCHAR(20) NOT NULL,
    end_time VARCHAR(20) NOT NULL,
    room VARCHAR(50),
    semester INTEGER DEFAULT 1,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE transport_allocations (
    id VARCHAR(100) PRIMARY KEY,
    user_id VARCHAR(100) NOT NULL,
    user_type VARCHAR(50) NOT NULL, -- 'student' or 'faculty'
    route_id VARCHAR(100) NOT NULL,
    boarding_stop_id VARCHAR(100) NOT NULL,
    boarding_stop_name VARCHAR(255) NOT NULL,
    seat_number VARCHAR(50) NOT NULL,
    pass_number VARCHAR(100) NOT NULL UNIQUE,
    status VARCHAR(50) DEFAULT 'active',
    valid_until VARCHAR(100) DEFAULT 'May 31, 2027',
    academic_year VARCHAR(50) DEFAULT '2025-2026',
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (route_id) REFERENCES transport_routes(id),
    FOREIGN KEY (user_id) REFERENCES user_profiles(id)
);
CREATE TABLE transport_live_tracking (
    route_id VARCHAR(100) PRIMARY KEY,
    bus_registration VARCHAR(100) NOT NULL,
    current_latitude REAL NOT NULL,
    current_longitude REAL NOT NULL,
    speed_kmh REAL DEFAULT 35.0,
    heading_deg REAL DEFAULT 45.0,
    current_stop_id VARCHAR(100),
    current_stop_name VARCHAR(255),
    next_stop_id VARCHAR(100),
    next_stop_name VARCHAR(255),
    eta_next_stop_minutes INTEGER DEFAULT 4,
    distance_to_destination_km REAL DEFAULT 5.2,
    trip_direction VARCHAR(50) DEFAULT 'morning_to_campus',
    transit_status VARCHAR(50) DEFAULT 'in_transit',
    last_ping_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    is_delay_reported BOOLEAN DEFAULT 0,
    delay_reason TEXT,
    FOREIGN KEY (route_id) REFERENCES transport_routes(id)
);
CREATE TABLE transport_routes (
    id VARCHAR(100) PRIMARY KEY,
    route_number VARCHAR(100) NOT NULL,
    name VARCHAR(255) NOT NULL,
    start_point VARCHAR(255) NOT NULL,
    destination VARCHAR(255) NOT NULL,
    bus_registration VARCHAR(100) NOT NULL,
    driver_name VARCHAR(255) NOT NULL,
    driver_phone VARCHAR(50) NOT NULL,
    total_stops INTEGER DEFAULT 0,
    morning_departure VARCHAR(50) NOT NULL,
    morning_arrival_sfrc VARCHAR(50) NOT NULL,
    evening_departure_sfrc VARCHAR(50) NOT NULL,
    evening_arrival_terminus VARCHAR(50) NOT NULL,
    capacity INTEGER DEFAULT 40,
    occupied_seats INTEGER DEFAULT 0,
    note TEXT,
    stops TEXT DEFAULT '[]',
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE user_profiles (
        id TEXT PRIMARY KEY,
        email TEXT UNIQUE NOT NULL,
        role TEXT NOT NULL,
        full_name TEXT NOT NULL,
        phone TEXT,
        avatar_url TEXT,
        department_id TEXT,
        department_name TEXT,
        is_active BOOLEAN DEFAULT 1,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    , preferences TEXT DEFAULT '{}');
CREATE TABLE ywed_enrollments (
        id TEXT PRIMARY KEY,
        course_id TEXT NOT NULL,
        user_id TEXT NOT NULL,
        student_name TEXT,
        register_number TEXT,
        status TEXT DEFAULT 'enrolled',
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE UNIQUE INDEX idx_parents_user_ward ON parents(user_id, ward_student_id);
CREATE VIEW complaints AS 
    SELECT id, reference, user_id, reporter_name, reporter_email, category, subject, description, is_anonymous, status, created_at, updated_at, resolved_at 
    FROM student_grievances;
COMMIT;