INSERT INTO "research_projects" VALUES('proj-cs-01','fac-cs-01','AI-Driven Precision Agriculture & Pest Detection in Cotton Fields','Dr. R. Meenakshi','Dr. S. Kavitha','CS','DST-SERB (Science & Engineering Research Board)','Major',2850000,'2024-04-01','2027-03-31','Ongoing','Developing deep learning edge inference architectures for real-time mobile disease diagnostics for regional farmers.','DST/SERB/CRG/2024/004921','2026-10-08 17:23:04','2026-10-08 17:23:04');
INSERT INTO "research_projects" VALUES('proj-chem-02','fac-chem-01','Green Synthesis of Bio-Nanocomposites for Industrial Wastewater Remediation','Dr. K. Arulmozhi',NULL,'CHEM','UGC (University Grants Commission)','Major',1650000,'2023-08-01','2026-07-31','Ongoing','Utilizing agricultural waste extracts for catalytic dye degradation and heavy metal removal from textile effluents.','UGC/MRP/CHEM/2023/1182','2026-10-08 17:23:04','2026-10-08 17:23:04');
